add_action( 'woocommerce_review_order_before_submit', 'perfectpixel_privacy_checkbox_classic', 9 );
add_action( 'woocommerce_checkout_process', 'perfectpixel_privacy_checkbox_classic_validate' );

function perfectpixel_privacy_checkbox_classic() {
	$text = esc_html( '{{privacy_checkbox_text}}' );
	$url  = get_privacy_policy_url();
	if ( $url ) {
		$text = '<a href="' . esc_url( $url ) . '" target="_blank" rel="noopener">' . $text . '</a>';
	}
	echo '<p class="form-row validate-required perfectpixel-privacy"><label class="woocommerce-form__label woocommerce-form__label-for-checkbox checkbox">';
	echo '<input type="checkbox" class="woocommerce-form__input woocommerce-form__input-checkbox input-checkbox" name="perfectpixel_privacy" value="1"> ';
	echo '<span>' . $text . '</span>&nbsp;<abbr class="required">*</abbr></label></p>'; // phpcs:ignore WordPress.Security.EscapeOutput -- Escaped above.
}

function perfectpixel_privacy_checkbox_classic_validate() {
	if ( empty( $_POST['perfectpixel_privacy'] ) ) { // phpcs:ignore WordPress.Security.NonceVerification
		wc_add_notice( esc_html( '{{privacy_checkbox_error}}' ), 'error' );
	}
}
